; Connections: 3


gameflow_node_gf_start_1764189149797:
    ; Start Node - transition to first connected node
    ld hl, gameflow_node_gfn_1764679490292
    jp execute_gameflow_node

gameflow_node_gfn_1764189161182:
    ; WorldLink Node - Load world: worldmap_1764189091692
    call init_sprites
    call init_components
    call init_entities
    call load_world_worldmap_1764189091692
    ; CRITICAL: Set game flow state and update sprites to VRAM
    ld a, FLOW_STATE_GAME
    ld (current_flow_state), a
    call update_sprites_to_vram   ; Copy sprite attributes to VRAM

    jp main_loop

gameflow_node_gfn_1764191316366:
    ; Restart Node
    jp init_rom  ; Restart entire game

gameflow_node_gfn_1764679490292:
    ; Globals Node (not yet implemented)
